(function() {
    'use strict';

    var uuid, avatar, color, cat;

    // Assign a uuid made of a random cat and a random color
    var randomColor = function() {
        var colors = ['navy', 'slate', 'olive', 'moss', 'chocolate', 'buttercup', 'maroon', 'cerise', 'plum', 'orchid'];
        return colors[(Math.random() * colors.length) >>> 0];
    };

    var randomCat = function() {
        var cats = ['tabby', 'bengal', 'persian', 'mainecoon', 'ragdoll', 'sphynx', 'siamese', 'korat', 'japanesebobtail', 'abyssinian', 'scottishfold'];
        return cats[(Math.random() * cats.length) >>> 0];
    };

    color = randomColor();
    cat = randomCat();
    uuid = color + '-' + cat;
    avatar = 'images/' + cat + '.jpg';

    function showNewest() {
        //document.querySelector('core-scaffold').$.headerPanel.scroller.scrollTop = document.querySelector('.chat-list').scrollHeight;
        var chatDiv = document.querySelector('.chat-list');
        chatDiv.scrollTop = chatDiv.scrollHeight;
    }

    /* Polymer UI and UX */

    var template = document.querySelector('#tmpl');

    template.addEventListener('dom-change', function() {
        var sub = template.$.sub;

        template.channel = 'polymer-chat';
        template.uuid = uuid;
        template.avatar = avatar;
        template.color = color;

        template.checkKey = function(e) {
            if (e.keyCode === 13 || e.charCode === 13) {
                template.publish();
            }
        };

        template.sendMyMessage = function(e) {
            template.publish();
        };

        template.messageList = [];


        /* PubNub Realtime Chat */

        var pastMsgs = [];
        var onlineUuids = [];

        template.getListWithOnlineStatus = function(list) {
            [].forEach.call(list, function(l) {
                // sanitize avatars
                var catName = (l.uuid + '').split('-')[1];
                l.avatar = 'images/' + catName + '.jpg';

                if (catName === undefined || /\s/.test(l.uuid)) {
                    l.uuid = 'fail-cat';
                    console.log('Oh you, I made this demo open so nice devs can play with, but you are soiling everything :-(');
                }

                if (onlineUuids.indexOf(l.uuid) > -1) {
                    l.status = 'online';
                } else {
                    l.status = 'offline';
                }
            });
            return list;
        };

        template.displayChatList = function(list) {
            template.messageList = list;
            // scroll to bottom when all list items are displayed
            template.async(showNewest);
        };

        template.subscribeCallback = function(e) {
            if (template.$.sub.messages.length > 0) {
                this.displayChatList(pastMsgs.concat(this.getListWithOnlineStatus(template.$.sub.messages)));
            }
        };

        template.presenceChanged = function(e) {
            var i = 0;
            var l = template.$.sub.presence.length;
            var d = template.$.sub.presence[l - 1];

            // how many users
            template.occupancy = d.occupancy;

            // who are online
            if (d.action === 'join') {
                if (d.uuid.length > 35) { // console
                    d.uuid = 'the-mighty-big-cat';
                }
                onlineUuids.push(d.uuid);
            } else {
                var idx = onlineUuids.indexOf(d.uuid);
                if (idx > -1) {
                    onlineUuids.splice(idx, 1);
                }
            }

            i++;

            // display at the left column
            template.cats = onlineUuids;
            // update the status at the main column
            if (template.messageList.length > 0) {
                template.messageList = this.getListWithOnlineStatus(template.messageList);
            }
        };

        template.historyRetrieved = function(e) {
            if (e.detail[0].length > 0) {
                pastMsgs = this.getListWithOnlineStatus(e.detail[0]);
                this.displayChatList(pastMsgs);
            }
        };

        template.publish = function() {
            if (!template.input) return;

            template.$.pub.message = {
                uuid: uuid,
                avatar: avatar,
                color: color,
                text: template.input,
                timestamp: new Date().toISOString()
            };
            template.$.pub.publish();
            template.input = '';
        };

        template.error = function(e) {
            console.log(e);
        };

    });


})();

var Polychat = function() {

  var self = this;
  self.name = 'Anonymous';
  self.users = {};
  self.user = null;
  self.messages = null;
  self.typingInterval = null;
  self.language = 'en';

  self.connect = function() {

    var fb = new Firebase('https://dpe-polychat.firebaseio.com/');
    var users = fb.child('users');

    self.user = users.child(self.name);
    self.user.set(false);
    self.user.onDisconnect().remove();
    users.once('value', function(snapshot) {
      self.users = snapshot.val();
      self.onUsers(self.users);
    });

    users.on('child_added', function(snapshot) {
      var name = snapshot.key();
      self.users[name] = false;
      if (name == self.name) {
        setTimeout(function() {
          self.onJoin(name);
        }, 2000);
      } else {
        self.onJoin(name);
      }
      self.onUsers(self.users);
    });

    users.on('child_removed', function(snapshot) {
      var name = snapshot.key();
      delete self.users[name]
      self.onLeave(name);
      self.onUsers(self.users);
    });

    users.on('child_changed', function(snapshot) {
      var name = snapshot.key();
      var typing = snapshot.val();
      self.users[name] = typing;
      self.onChange(name, typing);
      self.onUsers(self.users);
    });

    self.messages = fb.child('messages');
    self.messages.limitToLast(5).on('child_added', function(snapshot) {
      var message = snapshot.val();
      self.onMessage(message.name, message.text, message.language || 'en');
    });

  };

  self.onUsers = function(users) {
    console.log('Users changed:', users);
  };

  self.onJoin = function(name) {
    self.onMessage(name, 'joins');
  };

  self.onLeave = function(name) {
    self.onMessage(name, 'leaves');
  };

  self.onChange = function(name, typing) {
    self.onMessage(name, typing ? 'is typing' : 'stopped typing');
  };

  self.onMessage = function(name, text, language) {
    console.log(name + ': ' + text + ' [' + language + ']');
  };

  self.send = function(text) {
    if (self.messages != null) {
      self.messages.push({
        type: 'message',
        name: self.name,
        text: text,
        language: self.language
      });
    }
  };

  self.typing = function(typing) {
    var clear = function() {
      self.typingInterval = null;
      self.user.set(false);
    };
    if (self.user != null) {
      if (self.typingInterval != null) {
        clearTimeout(self.typingInterval);
      }
      if (typing) {
        if (self.typingInterval == null) {
          self.user.set(true);
        }
        self.typingInterval = setTimeout(clear, 3000);
      } else {
        clear();
      }
    }
  };

};
